cd /workspace/projects/01

cat > Not.hdl <<'EOF'
// File name: projects/01/Not.hdl
CHIP Not {
    IN in;
    OUT out;
    PARTS:
    Nand(a=in, b=in, out=out);
}
EOF

cat > And.hdl <<'EOF'
// File name: projects/01/And.hdl
CHIP And {
    IN a, b;
    OUT out;
    PARTS:
    Nand(a=a, b=b, out=nandOut);
    Not(in=nandOut, out=out);
}
EOF

cat > Or.hdl <<'EOF'
// File name: projects/01/Or.hdl
CHIP Or {
    IN a, b;
    OUT out;
    PARTS:
    Not(in=a, out=notA);
    Not(in=b, out=notB);
    Nand(a=notA, b=notB, out=nandOut);
    Not(in=nandOut, out=notNandOut);
    Not(in=notNandOut, out=out);
}
