#!/usr/bin/env python3
"""A small nand2tetris simulator: HDL elaboration + .tst script execution.

Used to verify the chips in projects/01..05 and the assembly programs in
projects/04 and projects/06 against the official .cmp comparison files.
"""

import os
import re
import sys

# --------------------------------------------------------------------------
# HDL parsing
# --------------------------------------------------------------------------


def strip_comments(text):
    text = re.sub(r"/\*.*?\*/", " ", text, flags=re.S)
    text = re.sub(r"//[^\n]*", " ", text)
    return text


class Conn(object):
    __slots__ = ("sub", "sub_lo", "sub_hi", "ext", "ext_lo", "ext_hi")

    def __init__(self, sub, sub_lo, sub_hi, ext, ext_lo, ext_hi):
        self.sub, self.sub_lo, self.sub_hi = sub, sub_lo, sub_hi
        self.ext, self.ext_lo, self.ext_hi = ext, ext_lo, ext_hi

    def sub_indices(self, width):
        if self.sub_lo is None:
            return list(range(width))
        return list(range(self.sub_lo, self.sub_hi + 1))

    def ext_indices(self, n):
        if self.ext_lo is None:
            return list(range(n))
        return list(range(self.ext_lo, self.ext_hi + 1))


class Part(object):
    __slots__ = ("name", "conns")

    def __init__(self, name, conns):
        self.name = name
        self.conns = conns


class Chip(object):
    __slots__ = ("name", "ins", "outs", "parts", "path")

    def __init__(self, name, ins, outs, parts, path):
        self.name = name
        self.ins = ins
        self.outs = outs
        self.parts = parts
        self.path = path

    def pin_widths(self):
        d = {}
        for n, w in self.ins:
            d[n] = (w, True)
        for n, w in self.outs:
            d[n] = (w, False)
        return d


PIN_RE = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)(?:\[(\d+)\])?$")
REF_RE = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)(?:\[(\d+)(?:\.\.(\d+))?\])?$")


def parse_pin_list(text):
    pins = []
    text = text.strip()
    if not text:
        return pins
    for item in text.split(","):
        item = item.strip()
        if not item:
            continue
        m = PIN_RE.match(item)
        if not m:
            raise ValueError("bad pin declaration: %r" % item)
        pins.append((m.group(1), int(m.group(2)) if m.group(2) else 1))
    return pins


def parse_ref(text):
    m = REF_RE.match(text.strip())
    if not m:
        raise ValueError("bad pin reference: %r" % text)
    name = m.group(1)
    if m.group(2) is None:
        return name, None, None
    lo = int(m.group(2))
    hi = int(m.group(3)) if m.group(3) is not None else lo
    return name, lo, hi


def parse_hdl(path):
    with open(path) as fh:
        text = strip_comments(fh.read())
    m = re.search(r"\bCHIP\s+([A-Za-z_][A-Za-z0-9_]*)\s*\{(.*)\}", text, re.S)
    if not m:
        raise ValueError("no CHIP declaration in %s" % path)
    name, body = m.group(1), m.group(2)

    ins, outs = [], []
    mi = re.search(r"\bIN\b([^;]*);", body)
    if mi:
        ins = parse_pin_list(mi.group(1))
    mo = re.search(r"\bOUT\b([^;]*);", body)
    if mo:
        outs = parse_pin_list(mo.group(1))

    mp = re.search(r"\bPARTS\s*:", body)
    parts_text = body[mp.end():] if mp else ""

    parts = []
    for pm in re.finditer(r"([A-Za-z_][A-Za-z0-9_]*)\s*\(([^)]*)\)\s*;", parts_text):
        pname, args = pm.group(1), pm.group(2)
        conns = []
        for arg in args.split(","):
            arg = arg.strip()
            if not arg:
                continue
            if "=" not in arg:
                raise ValueError("bad connection %r in %s" % (arg, path))
            lhs, rhs = arg.split("=", 1)
            sn, slo, shi = parse_ref(lhs)
            en, elo, ehi = parse_ref(rhs)
            conns.append(Conn(sn, slo, shi, en, elo, ehi))
        parts.append(Part(pname, conns))
    return Chip(name, ins, outs, parts, path)


# --------------------------------------------------------------------------
# Netlist / union-find over single-bit nets (net 0 = false, net 1 = true)
# --------------------------------------------------------------------------


class Netlist(object):
    def __init__(self):
        self.parent = [0, 1]

    def new(self):
        n = len(self.parent)
        self.parent.append(n)
        return n

    def find(self, x):
        p = self.parent
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if rb < ra:
            ra, rb = rb, ra
        self.parent[rb] = ra


# --------------------------------------------------------------------------
# Native (built-in) chips
# --------------------------------------------------------------------------


def bits_to_val(nets, V):
    v = 0
    for i, n in enumerate(nets):
        if V[n]:
            v |= 1 << i
    return v


def val_to_bits(val, nets, V):
    for i, n in enumerate(nets):
        V[n] = (val >> i) & 1


class Gate(object):
    clocked = False

    def comb_in_nets(self):
        return []

    def out_nets(self):
        return []

    def compute(self, V):
        pass

    def capture(self, V):
        pass

    def commit(self):
        pass

    def get_state(self, index):
        raise KeyError("chip has no addressable state")

    def set_state(self, index, value):
        raise KeyError("chip has no addressable state")


class NandGate(Gate):
    __slots__ = ("a", "b", "o")

    def __init__(self, pins):
        self.a = pins["a"][0]
        self.b = pins["b"][0]
        self.o = pins["out"][0]

    def comb_in_nets(self):
        return [self.a, self.b]

    def out_nets(self):
        return [self.o]

    def compute(self, V):
        V[self.o] = 1 - (V[self.a] & V[self.b])


class DFFGate(Gate):
    clocked = True
    __slots__ = ("i", "o", "state", "pending")

    def __init__(self, pins):
        self.i = pins["in"][0]
        self.o = pins["out"][0]
        self.state = 0
        self.pending = 0

    def out_nets(self):
        return [self.o]

    def compute(self, V):
        V[self.o] = self.state

    def capture(self, V):
        self.pending = V[self.i]

    def commit(self):
        self.state = self.pending

    def get_state(self, index):
        return self.state

    def set_state(self, index, value):
        self.state = value & 1
        self.pending = self.state


class RegisterGate(Gate):
    clocked = True

    def __init__(self, pins, width=16):
        self.width = width
        self.i = pins["in"]
        self.load = pins["load"][0]
        self.o = pins["out"]
        self.state = 0
        self.pending = 0

    def out_nets(self):
        return list(self.o)

    def compute(self, V):
        val_to_bits(self.state, self.o, V)

    def capture(self, V):
        self.pending = bits_to_val(self.i, V) if V[self.load] else self.state

    def commit(self):
        self.state = self.pending

    def get_state(self, index):
        return self.state

    def set_state(self, index, value):
        self.state = value & ((1 << self.width) - 1)
        self.pending = self.state


class PCGate(Gate):
    clocked = True

    def __init__(self, pins):
        self.i = pins["in"]
        self.load = pins["load"][0]
        self.inc = pins["inc"][0]
        self.reset = pins["reset"][0]
        self.o = pins["out"]
        self.state = 0
        self.pending = 0

    def out_nets(self):
        return list(self.o)

    def compute(self, V):
        val_to_bits(self.state, self.o, V)

    def capture(self, V):
        if V[self.reset]:
            self.pending = 0
        elif V[self.load]:
            self.pending = bits_to_val(self.i, V)
        elif V[self.inc]:
            self.pending = (self.state + 1) & 0xFFFF
        else:
            self.pending = self.state

    def commit(self):
        self.state = self.pending

    def get_state(self, index):
        return self.state

    def set_state(self, index, value):
        self.state = value & 0xFFFF
        self.pending = self.state


class RAMGate(Gate):
    clocked = True

    def __init__(self, pins, size):
        self.i = pins["in"]
        self.load = pins["load"][0]
        self.addr = pins["address"]
        self.o = pins["out"]
        self.mem = [0] * size
        self.size = size
        self.pending = None

    def comb_in_nets(self):
        return list(self.addr)

    def out_nets(self):
        return list(self.o)

    def compute(self, V):
        a = bits_to_val(self.addr, V)
        val_to_bits(self.mem[a] if a < self.size else 0, self.o, V)

    def capture(self, V):
        if V[self.load]:
            self.pending = (bits_to_val(self.addr, V), bits_to_val(self.i, V))
        else:
            self.pending = None

    def commit(self):
        if self.pending is not None:
            a, v = self.pending
            if a < self.size:
                self.mem[a] = v
            self.pending = None

    def get_state(self, index):
        return self.mem[index]

    def set_state(self, index, value):
        self.mem[index] = value & 0xFFFF


class ROM32KGate(Gate):
    def __init__(self, pins):
        self.addr = pins["address"]
        self.o = pins["out"]
        self.mem = [0] * 32768

    def comb_in_nets(self):
        return list(self.addr)

    def out_nets(self):
        return list(self.o)

    def compute(self, V):
        val_to_bits(self.mem[bits_to_val(self.addr, V)], self.o, V)

    def get_state(self, index):
        return self.mem[index]

    def set_state(self, index, value):
        self.mem[index] = value & 0xFFFF


class KeyboardGate(Gate):
    def __init__(self, pins):
        self.o = pins["out"]
        self.value = 0

    def out_nets(self):
        return list(self.o)

    def compute(self, V):
        val_to_bits(self.value, self.o, V)

    def get_state(self, index):
        return self.value

    def set_state(self, index, value):
        self.value = value & 0xFFFF


class NativeSpec(object):
    def __init__(self, ins, outs, factory):
        self.ins = ins
        self.outs = outs
        self.factory = factory

    def pin_widths(self):
        d = {}
        for n, w in self.ins:
            d[n] = (w, True)
        for n, w in self.outs:
            d[n] = (w, False)
        return d


def _reg_spec(width=16):
    return NativeSpec(
        [("in", width), ("load", 1)], [("out", width)],
        lambda pins, w=width: RegisterGate(pins, w))


def _ram_spec(bits):
    return NativeSpec(
        [("in", 16), ("load", 1), ("address", bits)], [("out", 16)],
        lambda pins, s=1 << bits: RAMGate(pins, s))


NATIVE_SPECS = {
    "Nand": NativeSpec([("a", 1), ("b", 1)], [("out", 1)], NandGate),
    "DFF": NativeSpec([("in", 1)], [("out", 1)], DFFGate),
    "Bit": _reg_spec(1),
    "Register": _reg_spec(16),
    "ARegister": _reg_spec(16),
    "DRegister": _reg_spec(16),
    "PC": NativeSpec(
        [("in", 16), ("load", 1), ("inc", 1), ("reset", 1)], [("out", 16)],
        PCGate),
    "RAM8": _ram_spec(3),
    "RAM64": _ram_spec(6),
    "RAM512": _ram_spec(9),
    "RAM4K": _ram_spec(12),
    "RAM16K": _ram_spec(14),
    "Screen": NativeSpec(
        [("in", 16), ("load", 1), ("address", 13)], [("out", 16)],
        lambda pins: RAMGate(pins, 8192)),
    "Keyboard": NativeSpec([], [("out", 16)], KeyboardGate),
    "ROM32K": NativeSpec([("address", 15)], [("out", 16)], ROM32KGate),
}

# Chips that are always taken from the native library (never elaborated from
# HDL) when they appear as a *part*.  The chip under test is always loaded
# from its HDL file.
DEFAULT_NATIVES = frozenset([
    "Nand", "DFF", "ARegister", "DRegister", "PC", "ROM32K", "Screen",
    "Keyboard", "RAM64", "RAM512", "RAM4K", "RAM16K",
])


# --------------------------------------------------------------------------
# Elaboration
# --------------------------------------------------------------------------


class HDLError(Exception):
    pass


class Simulator(object):
    def __init__(self, top_path, search_paths, natives=DEFAULT_NATIVES):
        self.search_paths = list(search_paths)
        self.natives = set(natives)
        self.cache = {}
        self.nl = Netlist()
        self.gates = []
        self.instances = {}

        top = parse_hdl(top_path)
        self.top = top
        self.pin_nets = {}
        self.pin_width = {}
        for n, w in top.ins + top.outs:
            self.pin_nets[n] = [self.nl.new() for _ in range(w)]
            self.pin_width[n] = w
        self._elaborate(top, dict(self.pin_nets), 0)
        self._finalize()

    # -- chip resolution ---------------------------------------------------
    def _find_hdl(self, name, refdir):
        for d in [refdir] + self.search_paths:
            if d is None:
                continue
            p = os.path.join(d, name + ".hdl")
            if os.path.exists(p):
                return p
        return None

    def _resolve(self, name, refdir):
        if name in self.natives:
            return NATIVE_SPECS[name]
        key = (name, refdir)
        if key in self.cache:
            return self.cache[key]
        path = self._find_hdl(name, refdir)
        if path is None:
            if name in NATIVE_SPECS:
                self.cache[key] = NATIVE_SPECS[name]
                return NATIVE_SPECS[name]
            raise HDLError("cannot resolve chip %s (from %s)" % (name, refdir))
        chip = parse_hdl(path)
        self.cache[key] = chip
        return chip

    # -- elaboration -------------------------------------------------------
    def _wire_net(self, wires, name, idx):
        lst = wires.get(name)
        if lst is None:
            lst = []
            wires[name] = lst
        while len(lst) <= idx:
            lst.append(self.nl.new())
        return lst[idx]

    def _elaborate(self, chip, io_nets, depth):
        if depth > 64:
            raise HDLError("chip nesting too deep (recursive definition?)")
        refdir = os.path.dirname(chip.path)
        wires = dict((k, list(v)) for k, v in io_nets.items())
        for part in chip.parts:
            sub = self._resolve(part.name, refdir)
            pw = sub.pin_widths()
            subnets = {}
            for p, (w, _isin) in pw.items():
                subnets[p] = [self.nl.new() for _ in range(w)]
            connected = dict((p, set()) for p in pw)

            for c in part.conns:
                if c.sub not in pw:
                    raise HDLError("%s: chip %s has no pin %s"
                                   % (chip.name, part.name, c.sub))
                w = pw[c.sub][0]
                sidx = c.sub_indices(w)
                for i in sidx:
                    if i >= w:
                        raise HDLError("%s: %s.%s index %d out of range"
                                       % (chip.name, part.name, c.sub, i))
                low = c.ext.lower()
                if low in ("true", "false") and c.ext_lo is None:
                    ext = [1 if low == "true" else 0] * len(sidx)
                else:
                    eidx = c.ext_indices(len(sidx))
                    ext = [self._wire_net(wires, c.ext, i) for i in eidx]
                if len(ext) != len(sidx):
                    raise HDLError("%s: width mismatch on %s.%s"
                                   % (chip.name, part.name, c.sub))
                for si, en in zip(sidx, ext):
                    self.nl.union(subnets[c.sub][si], en)
                    connected[c.sub].add(si)

            for p, (w, isin) in pw.items():
                if isin:
                    for i in range(w):
                        if i not in connected[p]:
                            self.nl.union(subnets[p][i], 0)

            if isinstance(sub, Chip):
                self._elaborate(sub, subnets, depth + 1)
            else:
                inst = sub.factory(subnets)
                self.gates.append(inst)
                self.instances.setdefault(part.name, []).append(inst)

    def _finalize(self):
        find = self.nl.find
        for name, nets in self.pin_nets.items():
            self.pin_nets[name] = [find(n) for n in nets]
        for g in self.gates:
            for attr in ("a", "b", "o", "i", "load", "inc", "reset", "addr"):
                if hasattr(g, attr):
                    v = getattr(g, attr)
                    if isinstance(v, list):
                        setattr(g, attr, [find(n) for n in v])
                    else:
                        setattr(g, attr, find(v))
        self.V = [0] * len(self.nl.parent)
        self.V[1] = 1

        driver = {}
        for idx, g in enumerate(self.gates):
            for n in g.out_nets():
                driver[n] = idx

        # Kahn topological sort over combinational dependencies.
        n = len(self.gates)
        succ = [[] for _ in range(n)]
        indeg = [0] * n
        for idx, g in enumerate(self.gates):
            seen = set()
            for net in g.comb_in_nets():
                d = driver.get(net)
                if d is not None and d != idx and d not in seen:
                    seen.add(d)
                    succ[d].append(idx)
                    indeg[idx] += 1
        order = [i for i in range(n) if indeg[i] == 0]
        out = []
        qi = 0
        while qi < len(order):
            i = order[qi]
            qi += 1
            out.append(i)
            for j in succ[i]:
                indeg[j] -= 1
                if indeg[j] == 0:
                    order.append(j)
        if len(out) != n:
            raise HDLError("combinational cycle detected in %s" % self.top.name)
        self.order = [self.gates[i] for i in out]
        self.clocked = [g for g in self.gates if g.clocked]

    # -- simulation --------------------------------------------------------
    def eval(self):
        V = self.V
        V[0] = 0
        V[1] = 1
        for g in self.order:
            g.compute(V)

    def tick(self):
        self.eval()
        for g in self.clocked:
            g.capture(self.V)

    def tock(self):
        for g in self.clocked:
            g.commit()
        self.eval()

    # -- variable access ---------------------------------------------------
    def get_instance(self, name):
        lst = self.instances.get(name)
        if not lst:
            raise KeyError("no part named %s in %s" % (name, self.top.name))
        return lst[0]

    def get_var(self, name, index):
        if index is None and name in self.pin_nets:
            return bits_to_val(self.pin_nets[name], self.V)
        inst = self.get_instance(name)
        return inst.get_state(index if index is not None else 0)

    def set_var(self, name, index, value):
        if index is None and name in self.pin_nets:
            val_to_bits(value, self.pin_nets[name], self.V)
            return
        inst = self.get_instance(name)
        inst.set_state(index if index is not None else 0, value)

    def var_width(self, name, index):
        if index is None and name in self.pin_width:
            return self.pin_width[name]
        return 16


