# Hack assembler + CPU emulator (for .asm test scripts)
# --------------------------------------------------------------------------

PREDEFINED = {
    "SP": 0, "LCL": 1, "ARG": 2, "THIS": 3, "THAT": 4,
    "SCREEN": 16384, "KBD": 24576,
}
for _i in range(16):
    PREDEFINED["R%d" % _i] = _i

COMP_CODES = {
    "0": 0b0101010, "1": 0b0111111, "-1": 0b0111010, "D": 0b0001100,
    "A": 0b0110000, "!D": 0b0001101, "!A": 0b0110001, "-D": 0b0001111,
    "-A": 0b0110011, "D+1": 0b0011111, "A+1": 0b0110111, "D-1": 0b0001110,
    "A-1": 0b0110010, "D+A": 0b0000010, "D-A": 0b0010011, "A-D": 0b0000111,
    "D&A": 0b0000000, "D|A": 0b0010101,
}
for _k in list(COMP_CODES):
    if "A" in _k:
        COMP_CODES[_k.replace("A", "M")] = COMP_CODES[_k] | 0b1000000
# common alternative spellings accepted by the official assembler
for _a, _b in (("D+A", "A+D"), ("D&A", "A&D"), ("D|A", "A|D"),
               ("D+M", "M+D"), ("D&M", "M&D"), ("D|M", "M|D")):
    COMP_CODES[_b] = COMP_CODES[_a]

JUMP_CODES = {"": 0, "JGT": 1, "JEQ": 2, "JGE": 3, "JLT": 4, "JNE": 5,
              "JLE": 6, "JMP": 7}


def assemble(path):
    with open(path) as fh:
        raw = fh.read()
    lines = []
    for line in raw.split("\n"):
        line = re.sub(r"//.*", "", line).strip()
        line = line.replace(" ", "").replace("\t", "")
        if line:
            lines.append(line)

    symbols = dict(PREDEFINED)
    pc = 0
    body = []
    for line in lines:
        if line.startswith("(") and line.endswith(")"):
            symbols[line[1:-1]] = pc
        else:
            body.append(line)
            pc += 1

    next_var = 16
    code = []
    for line in body:
        if line.startswith("@"):
            sym = line[1:]
            if sym.isdigit():
                val = int(sym)
            else:
                if sym not in symbols:
                    symbols[sym] = next_var
                    next_var += 1
                val = symbols[sym]
            code.append(val & 0x7FFF)
        else:
            jump = ""
            comp = line
            dest = ""
            if ";" in comp:
                comp, jump = comp.split(";", 1)
            if "=" in comp:
                dest, comp = comp.split("=", 1)
            if comp not in COMP_CODES:
                raise ValueError("bad comp %r in %s" % (comp, path))
            if jump not in JUMP_CODES:
                raise ValueError("bad jump %r in %s" % (jump, path))
            d = 0
            if "A" in dest:
                d |= 4
            if "D" in dest:
                d |= 2
            if "M" in dest:
                d |= 1
            code.append(0xE000 | (COMP_CODES[comp] << 6) | (d << 3)
                        | JUMP_CODES[jump])
    return code


def signed16(v):
    v &= 0xFFFF
    return v - 0x10000 if v & 0x8000 else v


class CPUEmulator(object):
    """Behavioural model matching the official CPU emulator's variables."""

    def __init__(self, program):
        self.rom = list(program) + [0] * (32768 - len(program))
        self.ram = [0] * 24577
        self.A = 0
        self.D = 0
        self.PC = 0

    def _comp(self, c):
        a = (c >> 6) & 1
        f = (c >> 0) & 0x3F
        y = self.ram[self.A] if a else self.A
        y &= 0xFFFF
        x = self.D & 0xFFFF
        zx = (f >> 5) & 1
        nx = (f >> 4) & 1
        zy = (f >> 3) & 1
        ny = (f >> 2) & 1
        fn = (f >> 1) & 1
        no = f & 1
        if zx:
            x = 0
        if nx:
            x ^= 0xFFFF
        if zy:
            y = 0
        if ny:
            y ^= 0xFFFF
        out = (x + y) & 0xFFFF if fn else (x & y)
        if no:
            out ^= 0xFFFF
        return out

    def step(self):
        instr = self.rom[self.PC & 0x7FFF]
        if instr & 0x8000 == 0:
            self.A = instr & 0x7FFF
            self.PC = (self.PC + 1) & 0x7FFF
            return
        out = self._comp((instr >> 6) & 0x7F)
        d = (instr >> 3) & 7
        j = instr & 7
        sv = signed16(out)
        jump = ((j & 1 and sv > 0) or (j & 2 and sv == 0) or (j & 4 and sv < 0))
        if d & 1:
            addr = self.A & 0x7FFF
            if addr < len(self.ram):
                self.ram[addr] = out
        if d & 2:
            self.D = out
        if d & 4:
            self.A = out & 0xFFFF
        self.PC = (self.A & 0x7FFF) if jump else ((self.PC + 1) & 0x7FFF)

    def get_var(self, name, index):
        if name in ("RAM", "Memory"):
            return self.ram[index]
        if name == "ROM":
            return self.rom[index]
        if name in ("A", "ARegister"):
            return self.A
        if name in ("D", "DRegister"):
            return self.D
        if name == "PC":
            return self.PC
        raise KeyError(name)

    def set_var(self, name, index, value):
        if name in ("RAM", "Memory"):
            self.ram[index] = value & 0xFFFF
        elif name in ("A", "ARegister"):
            self.A = value & 0xFFFF
        elif name in ("D", "DRegister"):
            self.D = value & 0xFFFF
        elif name == "PC":
            self.PC = value & 0x7FFF
        else:
            raise KeyError(name)

    def var_width(self, name, index):
        return 16


