# .tst script parsing / execution
# --------------------------------------------------------------------------

TOKEN_RE = re.compile(r'"[^"]*"|[,;{}]|[^\s,;{}]+')


def tokenize(text):
    return TOKEN_RE.findall(strip_comments(text))


class Fmt(object):
    __slots__ = ("name", "index", "code", "left", "width", "right", "label")

    def __init__(self, spec):
        m = re.match(r"^([A-Za-z_][A-Za-z0-9_]*)(?:\[(\d*)\])?"
                     r"%([BDXS])(\d+)\.(\d+)\.(\d+)$", spec)
        if not m:
            raise ValueError("bad output spec %r" % spec)
        self.name = m.group(1)
        if m.group(2) is None:
            self.index = None
            self.label = self.name
        elif m.group(2) == "":
            self.index = -1  # "[]" -> whole chip value
            self.label = self.name + "[]"
        else:
            self.index = int(m.group(2))
            self.label = "%s[%d]" % (self.name, self.index)
        self.code = m.group(3)
        self.left = int(m.group(4))
        self.width = int(m.group(5))
        self.right = int(m.group(6))

    def total(self):
        return self.left + self.width + self.right

    def header(self):
        t = self.total()
        lab = self.label[:t]
        pad = t - len(lab)
        return " " * (pad // 2) + lab + " " * (pad - pad // 2)

    def render(self, value):
        if self.code == "S":
            s = str(value)[:self.width]
            s = s + " " * (self.width - len(s))
        elif self.code == "B":
            v = int(value) & ((1 << self.width) - 1) if self.width < 64 else int(value)
            s = format(v, "0%db" % self.width)
            s = s[-self.width:]
        elif self.code == "X":
            v = int(value) & 0xFFFF
            s = format(v, "0%dX" % self.width)[-self.width:]
        else:
            s = str(signed16(int(value)))
            s = s.rjust(self.width)[-self.width:] if len(s) > self.width \
                else s.rjust(self.width)
        return " " * self.left + s + " " * self.right


def parse_value(tok):
    tok = tok.strip()
    if tok.startswith("%B") or tok.startswith("%b"):
        return int(tok[2:], 2)
    if tok.startswith("%X") or tok.startswith("%x"):
        return int(tok[2:], 16)
    if tok.startswith("%D") or tok.startswith("%d"):
        return int(tok[2:]) & 0xFFFF
    return int(tok) & 0xFFFF


VAR_RE = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)(?:\[(\d*)\])?$")


def parse_var(tok):
    m = VAR_RE.match(tok)
    if not m:
        raise ValueError("bad variable %r" % tok)
    if m.group(2) is None:
        return m.group(1), None
    if m.group(2) == "":
        return m.group(1), -1
    return m.group(1), int(m.group(2))


class ScriptRunner(object):
    def __init__(self, tst_path, natives=DEFAULT_NATIVES, search_paths=None,
                 max_steps=None, verbose=False):
        self.dir = os.path.dirname(os.path.abspath(tst_path))
        self.path = tst_path
        self.natives = natives
        self.search_paths = search_paths or []
        self.sim = None
        self.kind = None
        self.out_lines = []
        self.out_file = None
        self.cmp_file = None
        self.fmts = []
        self.ticks = 0
        self.phase = 0  # 0 = after tock, 1 = after tick
        self.echo = ""
        self.max_steps = max_steps
        self.verbose = verbose

    # -- variable plumbing -------------------------------------------------
    def _get(self, name, index):
        if name == "time":
            return "%d%s" % (self.ticks, "+" if self.phase else "")
        idx = None if index is None else (None if index == -1 else index)
        return self.sim.get_var(name, idx)

    def _set(self, name, index, value):
        idx = None if index is None else (None if index == -1 else index)
        self.sim.set_var(name, idx, value)

    # -- execution ---------------------------------------------------------
    def run(self):
        with open(self.path) as fh:
            toks = tokenize(fh.read())
        stmts = self._parse_block(toks, 0, len(toks))
        self._exec(stmts)
        return self._finish()

    def _parse_block(self, toks, i, end):
        stmts = []
        cur = []
        while i < end:
            t = toks[i]
            if t == "{":
                depth = 1
                j = i + 1
                while j < end and depth:
                    if toks[j] == "{":
                        depth += 1
                    elif toks[j] == "}":
                        depth -= 1
                    j += 1
                body = self._parse_block(toks, i + 1, j - 1)
                stmts.append(("block", cur, body))
                cur = []
                i = j
                continue
            if t in (",", ";"):
                if cur:
                    stmts.append(("cmd", cur))
                    cur = []
                i += 1
                continue
            cur.append(t)
            i += 1
        if cur:
            stmts.append(("cmd", cur))
        return stmts

    def _exec(self, stmts):
        for st in stmts:
            if st[0] == "cmd":
                self._command(st[1])
            else:
                head, body = st[1], st[2]
                if head and head[0] == "repeat":
                    n = int(head[1]) if len(head) > 1 else 1
                    if self.max_steps is not None:
                        n = min(n, self.max_steps)
                    for _ in range(n):
                        self._exec(body)
                elif head and head[0] == "while":
                    var, index = parse_var(head[1])
                    op = head[2]
                    val = parse_value(head[3])
                    guard = 0
                    while self._cond(self._get(var, index), op, val):
                        self._exec(body)
                        guard += 1
                        if guard > 100000:
                            raise RuntimeError("while loop did not terminate")
                else:
                    raise ValueError("unknown block head %r" % (head,))

    @staticmethod
    def _cond(a, op, b):
        a = signed16(a)
        b = signed16(b)
        return {"=": a == b, "<>": a != b, "<": a < b, ">": a > b,
                "<=": a <= b, ">=": a >= b}[op]

    def _command(self, toks):
        cmd = toks[0]
        if cmd == "load":
            target = toks[1]
            path = os.path.join(self.dir, target)
            if target.endswith(".hdl"):
                self.kind = "hdl"
                self.sim = Simulator(path, self.search_paths, self.natives)
            elif target.endswith(".asm"):
                self.kind = "cpu"
                self.sim = CPUEmulator(assemble(path))
            elif target.endswith(".hack"):
                self.kind = "cpu"
                self.sim = CPUEmulator(load_hack(path))
            else:
                raise ValueError("cannot load %s" % target)
        elif cmd == "output-file":
            self.out_file = os.path.join(self.dir, toks[1])
        elif cmd == "compare-to":
            self.cmp_file = os.path.join(self.dir, toks[1])
        elif cmd == "output-list":
            self.fmts = [Fmt(t) for t in toks[1:]]
            self.out_lines.append(
                "|" + "|".join(f.header() for f in self.fmts) + "|")
        elif cmd == "set":
            if len(toks) >= 4 and toks[1] == "ROM32K":
                raise ValueError("unexpected set form")
            name, index = parse_var(toks[1])
            self._set(name, index, parse_value(toks[2]))
        elif cmd == "eval":
            if self.kind == "hdl":
                self.sim.eval()
        elif cmd == "output":
            if self.kind == "hdl":
                self.sim.eval()
            self._emit()
        elif cmd == "tick":
            self._tick()
        elif cmd == "tock":
            self._tock()
        elif cmd == "ticktock":
            self._tick()
            self._tock()
        elif cmd == "echo":
            self.echo = toks[1].strip('"')
        elif cmd == "clear-echo":
            self.echo = ""
        elif cmd == "breakpoint":
            pass
        elif cmd == "ROM32K":
            # "ROM32K load Foo.hack"
            if len(toks) >= 3 and toks[1] == "load":
                rom = self.sim.get_instance("ROM32K")
                data = load_hack(os.path.join(self.dir, toks[2]))
                rom.mem = list(data) + [0] * (32768 - len(data))
            else:
                raise ValueError("unsupported ROM32K command %r" % (toks,))
        elif cmd in ("vmstep", "repeat", "while"):
            raise ValueError("unexpected %s outside block" % cmd)
        else:
            raise ValueError("unknown command %r" % (toks,))

    def _tick(self):
        if self.kind == "hdl":
            self.sim.tick()
        self.phase = 1

    def _tock(self):
        if self.kind == "hdl":
            self.sim.tock()
        else:
            self.sim.step()
        self.phase = 0
        self.ticks += 1

    def _emit(self):
        cells = []
        for f in self.fmts:
            cells.append(f.render(self._get(f.name, f.index)))
        self.out_lines.append("|" + "|".join(cells) + "|")

    def _finish(self):
        text = "\n".join(self.out_lines) + "\n"
        if self.out_file:
            with open(self.out_file, "w") as fh:
                fh.write(text)
        if not self.cmp_file or not os.path.exists(self.cmp_file):
            return True, "no comparison file"
        with open(self.cmp_file) as fh:
            expected = fh.read().split("\n")
        actual = text.split("\n")
        while expected and expected[-1] == "":
            expected.pop()
        while actual and actual[-1] == "":
            actual.pop()
        if self.max_steps is not None:
            return True, "partial run (%d lines)" % len(actual)
        n = min(len(expected), len(actual))
        for i in range(n):
            if not cmp_line(expected[i], actual[i]):
                return False, ("line %d\n  expected: %s\n  actual:   %s"
                               % (i + 1, expected[i], actual[i]))
        if len(expected) != len(actual):
            return False, ("line count mismatch: expected %d, got %d"
                           % (len(expected), len(actual)))
        return True, "%d lines match" % len(actual)


def cmp_line(exp, act):
    exp = exp.rstrip()
    act = act.rstrip()
    if len(exp) != len(act):
        return False
    for a, b in zip(exp, act):
        if a != "*" and a != b:
            return False
    return True


def load_hack(path):
    out = []
    with open(path) as fh:
        for line in fh:
            line = line.strip()
            if line:
                out.append(int(line, 2))
    return out


# --------------------------------------------------------------------------


def main(argv):
    import argparse
    ap = argparse.ArgumentParser()
    ap.add_argument("tst", nargs="+")
    ap.add_argument("--natives", default=None,
                    help="comma separated list of chips to treat as built-in")
    ap.add_argument("--search", default="",
                    help="comma separated extra HDL search directories")
    ap.add_argument("--max-steps", type=int, default=None)
    args = ap.parse_args(argv[1:])

    natives = DEFAULT_NATIVES
    if args.natives is not None:
        natives = set(x for x in args.natives.split(",") if x)
    search = [p for p in args.search.split(",") if p]

    failures = 0
    for tst in args.tst:
        try:
            runner = ScriptRunner(tst, natives, search, args.max_steps)
            ok, msg = runner.run()
        except Exception as exc:  # pragma: no cover - diagnostics
            ok, msg = False, "%s: %s" % (type(exc).__name__, exc)
        status = "PASS" if ok else "FAIL"
        if not ok:
            failures += 1
        print("%-4s %s  (%s)" % (status, tst, msg.replace("\n", "\n     ")))
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

