#!/usr/bin/env python3
"""A small nand2tetris simulator: HDL elaboration + .tst script execution.

Used to verify the chips in projects/01..05 and the assembly programs in
projects/04 and projects/06 against the official .cmp comparison files.
"""

import os
import re
import sys

# --------------------------------------------------------------------------
# HDL parsing
# --------------------------------------------------------------------------


def strip_comments(text):
    text = re.sub(r"/\*.*?\*/", " ", text, flags=re.S)
    text = re.sub(r"//[^\n]*", " ", text)
    return text


class Conn(object):
    __slots__ = ("sub", "sub_lo", "sub_hi", "ext", "ext_lo", "ext_hi")

    def __init__(self, sub, sub_lo, sub_hi, ext, ext_lo, ext_hi):
        self.sub, self.sub_lo, self.sub_hi = sub, sub_lo, sub_hi
        self.ext, self.ext_lo, self.ext_hi = ext, ext_lo, ext_hi

    def sub_indices(self, width):
        if self.sub_lo is None:
            return list(range(width))
        return list(range(self.sub_lo, self.sub_hi + 1))

    def ext_indices(self, n):
        if self.ext_lo is None:
            return list(range(n))
        return list(range(self.ext_lo, self.ext_hi + 1))


class Part(object):
    __slots__ = ("name", "conns")

    def __init__(self, name, conns):
        self.name = name
        self.conns = conns


class Chip(object):
    __slots__ = ("name", "ins", "outs", "parts", "path")

    def __init__(self, name, ins, outs, parts, path):
        self.name = name
        self.ins = ins
        self.outs = outs
        self.parts = parts
        self.path = path

    def pin_widths(self):
        d = {}
        for n, w in self.ins:
            d[n] = (w, True)
        for n, w in self.outs:
            d[n] = (w, False)
        return d


PIN_RE = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)(?:\[(\d+)\])?$")
REF_RE = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)(?:\[(\d+)(?:\.\.(\d+))?\])?$")


def parse_pin_list(text):
    pins = []
    text = text.strip()
    if not text:
        return pins
    for item in text.split(","):
        item = item.strip()
        if not item:
            continue
        m = PIN_RE.match(item)
        if not m:
            raise ValueError("bad pin declaration: %r" % item)
        pins.append((m.group(1), int(m.group(2)) if m.group(2) else 1))
    return pins


def parse_ref(text):
    m = REF_RE.match(text.strip())
    if not m:
        raise ValueError("bad pin reference: %r" % text)
    name = m.group(1)
    if m.group(2) is None:
        return name, None, None
    lo = int(m.group(2))
    hi = int(m.group(3)) if m.group(3) is not None else lo
    return name, lo, hi


def parse_hdl(path):
    with open(path) as fh:
        text = strip_comments(fh.read())
    m = re.search(r"\bCHIP\s+([A-Za-z_][A-Za-z0-9_]*)\s*\{(.*)\}", text, re.S)
    if not m:
        raise ValueError("no CHIP declaration in %s" % path)
    name, body = m.group(1), m.group(2)

    ins, outs = [], []
    mi = re.search(r"\bIN\b([^;]*);", body)
    if mi:
        ins = parse_pin_list(mi.group(1))
    mo = re.search(r"\bOUT\b([^;]*);", body)
    if mo:
        outs = parse_pin_list(mo.group(1))

    mp = re.search(r"\bPARTS\s*:", body)
    parts_text = body[mp.end():] if mp else ""

    parts = []
    for pm in re.finditer(r"([A-Za-z_][A-Za-z0-9_]*)\s*\(([^)]*)\)\s*;", parts_text):
        pname, args = pm.group(1), pm.group(2)
        conns = []
        for arg in args.split(","):
            arg = arg.strip()
            if not arg:
                continue
            if "=" not in arg:
                raise ValueError("bad connection %r in %s" % (arg, path))
            lhs, rhs = arg.split("=", 1)
            sn, slo, shi = parse_ref(lhs)
            en, elo, ehi = parse_ref(rhs)
            conns.append(Conn(sn, slo, shi, en, elo, ehi))
        parts.append(Part(pname, conns))
    return Chip(name, ins, outs, parts, path)


# --------------------------------------------------------------------------
# Netlist / union-find over single-bit nets (net 0 = false, net 1 = true)
# --------------------------------------------------------------------------


class Netlist(object):
    def __init__(self):
        self.parent = [0, 1]

    def new(self):
        n = len(self.parent)
        self.parent.append(n)
        return n

    def find(self, x):
        p = self.parent
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if rb < ra:
            ra, rb = rb, ra
        self.parent[rb] = ra


# --------------------------------------------------------------------------
# Native (built-in) chips
# --------------------------------------------------------------------------


def bits_to_val(nets, V):
    v = 0
    for i, n in enumerate(nets):
        if V[n]:
            v |= 1 << i
    return v


def val_to_bits(val, nets, V):
    for i, n in enumerate(nets):
        V[n] = (val >> i) & 1


class Gate(object):
    clocked = False

    def comb_in_nets(self):
        return []

    def out_nets(self):
        return []

    def compute(self, V):
        pass

    def capture(self, V):
        pass

    def commit(self):
        pass

    def get_state(self, index):
        raise KeyError("chip has no addressable state")

    def set_state(self, index, value):
        raise KeyError("chip has no addressable state")


class NandGate(Gate):
    __slots__ = ("a", "b", "o")

    def __init__(self, pins):
        self.a = pins["a"][0]
        self.b = pins["b"][0]
        self.o = pins["out"][0]

    def comb_in_nets(self):
        return [self.a, self.b]

    def out_nets(self):
        return [self.o]

    def compute(self, V):
        V[self.o] = 1 - (V[self.a] & V[self.b])


class DFFGate(Gate):
    clocked = True
    __slots__ = ("i", "o", "state", "pending")

    def __init__(self, pins):
        self.i = pins["in"][0]
        self.o = pins["out"][0]
        self.state = 0
        self.pending = 0

    def out_nets(self):
        return [self.o]

    def compute(self, V):
        V[self.o] = self.state

    def capture(self, V):
        self.pending = V[self.i]

    def commit(self):
        self.state = self.pending

    def get_state(self, index):
        return self.state

    def set_state(self, index, value):
        self.state = value & 1
        self.pending = self.state


class RegisterGate(Gate):
    clocked = True

    def __init__(self, pins, width=16):
        self.width = width
        self.i = pins["in"]
        self.load = pins["load"][0]
        self.o = pins["out"]
        self.state = 0
        self.pending = 0

    def out_nets(self):
        return list(self.o)

    def compute(self, V):
        val_to_bits(self.state, self.o, V)

    def capture(self, V):
        self.pending = bits_to_val(self.i, V) if V[self.load] else self.state

    def commit(self):
        self.state = self.pending

    def get_state(self, index):
        return self.state

    def set_state(self, index, value):
        self.state = value & ((1 << self.width) - 1)
        self.pending = self.state


class PCGate(Gate):
    clocked = True

    def __init__(self, pins):
        self.i = pins["in"]
        self.load = pins["load"][0]
        self.inc = pins["inc"][0]
        self.reset = pins["reset"][0]
        self.o = pins["out"]
        self.state = 0
        self.pending = 0

    def out_nets(self):
        return list(self.o)

    def compute(self, V):
        val_to_bits(self.state, self.o, V)

    def capture(self, V):
        if V[self.reset]:
            self.pending = 0
        elif V[self.load]:
            self.pending = bits_to_val(self.i, V)
        elif V[self.inc]:
            self.pending = (self.state + 1) & 0xFFFF
        else:
            self.pending = self.state

    def commit(self):
        self.state = self.pending

    def get_state(self, index):
        return self.state

    def set_state(self, index, value):
        self.state = value & 0xFFFF
        self.pending = self.state


class RAMGate(Gate):
    clocked = True

    def __init__(self, pins, size):
        self.i = pins["in"]
        self.load = pins["load"][0]
        self.addr = pins["address"]
        self.o = pins["out"]
        self.mem = [0] * size
        self.size = size
        self.pending = None

    def comb_in_nets(self):
        return list(self.addr)

    def out_nets(self):
        return list(self.o)

    def compute(self, V):
        a = bits_to_val(self.addr, V)
        val_to_bits(self.mem[a] if a < self.size else 0, self.o, V)

    def capture(self, V):
        if V[self.load]:
            self.pending = (bits_to_val(self.addr, V), bits_to_val(self.i, V))
        else:
            self.pending = None

    def commit(self):
        if self.pending is not None:
            a, v = self.pending
            if a < self.size:
                self.mem[a] = v
            self.pending = None

    def get_state(self, index):
        return self.mem[index]

    def set_state(self, index, value):
        self.mem[index] = value & 0xFFFF


class ROM32KGate(Gate):
    def __init__(self, pins):
        self.addr = pins["address"]
        self.o = pins["out"]
        self.mem = [0] * 32768

    def comb_in_nets(self):
        return list(self.addr)

    def out_nets(self):
        return list(self.o)

    def compute(self, V):
        val_to_bits(self.mem[bits_to_val(self.addr, V)], self.o, V)

    def get_state(self, index):
        return self.mem[index]

    def set_state(self, index, value):
        self.mem[index] = value & 0xFFFF


class KeyboardGate(Gate):
    def __init__(self, pins):
        self.o = pins["out"]
        self.value = 0

    def out_nets(self):
        return list(self.o)

    def compute(self, V):
        val_to_bits(self.value, self.o, V)

    def get_state(self, index):
        return self.value

    def set_state(self, index, value):
        self.value = value & 0xFFFF


class NativeSpec(object):
    def __init__(self, ins, outs, factory):
        self.ins = ins
        self.outs = outs
        self.factory = factory

    def pin_widths(self):
        d = {}
        for n, w in self.ins:
            d[n] = (w, True)
        for n, w in self.outs:
            d[n] = (w, False)
        return d


def _reg_spec(width=16):
    return NativeSpec(
        [("in", width), ("load", 1)], [("out", width)],
        lambda pins, w=width: RegisterGate(pins, w))


def _ram_spec(bits):
    return NativeSpec(
        [("in", 16), ("load", 1), ("address", bits)], [("out", 16)],
        lambda pins, s=1 << bits: RAMGate(pins, s))


NATIVE_SPECS = {
    "Nand": NativeSpec([("a", 1), ("b", 1)], [("out", 1)], NandGate),
    "DFF": NativeSpec([("in", 1)], [("out", 1)], DFFGate),
    "Bit": _reg_spec(1),
    "Register": _reg_spec(16),
    "ARegister": _reg_spec(16),
    "DRegister": _reg_spec(16),
    "PC": NativeSpec(
        [("in", 16), ("load", 1), ("inc", 1), ("reset", 1)], [("out", 16)],
        PCGate),
    "RAM8": _ram_spec(3),
    "RAM64": _ram_spec(6),
    "RAM512": _ram_spec(9),
    "RAM4K": _ram_spec(12),
    "RAM16K": _ram_spec(14),
    "Screen": NativeSpec(
        [("in", 16), ("load", 1), ("address", 13)], [("out", 16)],
        lambda pins: RAMGate(pins, 8192)),
    "Keyboard": NativeSpec([], [("out", 16)], KeyboardGate),
    "ROM32K": NativeSpec([("address", 15)], [("out", 16)], ROM32KGate),
}

# Chips that are always taken from the native library (never elaborated from
# HDL) when they appear as a *part*.  The chip under test is always loaded
# from its HDL file.
DEFAULT_NATIVES = frozenset([
    "Nand", "DFF", "ARegister", "DRegister", "PC", "ROM32K", "Screen",
    "Keyboard", "RAM64", "RAM512", "RAM4K", "RAM16K",
])


# --------------------------------------------------------------------------
# Elaboration
# --------------------------------------------------------------------------


class HDLError(Exception):
    pass


class Simulator(object):
    def __init__(self, top_path, search_paths, natives=DEFAULT_NATIVES):
        self.search_paths = list(search_paths)
        self.natives = set(natives)
        self.cache = {}
        self.nl = Netlist()
        self.gates = []
        self.instances = {}

        top = parse_hdl(top_path)
        self.top = top
        self.pin_nets = {}
        self.pin_width = {}
        for n, w in top.ins + top.outs:
            self.pin_nets[n] = [self.nl.new() for _ in range(w)]
            self.pin_width[n] = w
        self._elaborate(top, dict(self.pin_nets), 0)
        self._finalize()

    # -- chip resolution ---------------------------------------------------
    def _find_hdl(self, name, refdir):
        for d in [refdir] + self.search_paths:
            if d is None:
                continue
            p = os.path.join(d, name + ".hdl")
            if os.path.exists(p):
                return p
        return None

    def _resolve(self, name, refdir):
        if name in self.natives:
            return NATIVE_SPECS[name]
        key = (name, refdir)
        if key in self.cache:
            return self.cache[key]
        path = self._find_hdl(name, refdir)
        if path is None:
            if name in NATIVE_SPECS:
                self.cache[key] = NATIVE_SPECS[name]
                return NATIVE_SPECS[name]
            raise HDLError("cannot resolve chip %s (from %s)" % (name, refdir))
        chip = parse_hdl(path)
        self.cache[key] = chip
        return chip

    # -- elaboration -------------------------------------------------------
    def _wire_net(self, wires, name, idx):
        lst = wires.get(name)
        if lst is None:
            lst = []
            wires[name] = lst
        while len(lst) <= idx:
            lst.append(self.nl.new())
        return lst[idx]

    def _elaborate(self, chip, io_nets, depth):
        if depth > 64:
            raise HDLError("chip nesting too deep (recursive definition?)")
        refdir = os.path.dirname(chip.path)
        wires = dict((k, list(v)) for k, v in io_nets.items())
        for part in chip.parts:
            sub = self._resolve(part.name, refdir)
            pw = sub.pin_widths()
            subnets = {}
            for p, (w, _isin) in pw.items():
                subnets[p] = [self.nl.new() for _ in range(w)]
            connected = dict((p, set()) for p in pw)

            for c in part.conns:
                if c.sub not in pw:
                    raise HDLError("%s: chip %s has no pin %s"
                                   % (chip.name, part.name, c.sub))
                w = pw[c.sub][0]
                sidx = c.sub_indices(w)
                for i in sidx:
                    if i >= w:
                        raise HDLError("%s: %s.%s index %d out of range"
                                       % (chip.name, part.name, c.sub, i))
                low = c.ext.lower()
                if low in ("true", "false") and c.ext_lo is None:
                    ext = [1 if low == "true" else 0] * len(sidx)
                else:
                    eidx = c.ext_indices(len(sidx))
                    ext = [self._wire_net(wires, c.ext, i) for i in eidx]
                if len(ext) != len(sidx):
                    raise HDLError("%s: width mismatch on %s.%s"
                                   % (chip.name, part.name, c.sub))
                for si, en in zip(sidx, ext):
                    self.nl.union(subnets[c.sub][si], en)
                    connected[c.sub].add(si)

            for p, (w, isin) in pw.items():
                if isin:
                    for i in range(w):
                        if i not in connected[p]:
                            self.nl.union(subnets[p][i], 0)

            if isinstance(sub, Chip):
                self._elaborate(sub, subnets, depth + 1)
            else:
                inst = sub.factory(subnets)
                self.gates.append(inst)
                self.instances.setdefault(part.name, []).append(inst)

    def _finalize(self):
        find = self.nl.find
        for name, nets in self.pin_nets.items():
            self.pin_nets[name] = [find(n) for n in nets]
        for g in self.gates:
            for attr in ("a", "b", "o", "i", "load", "inc", "reset", "addr"):
                if hasattr(g, attr):
                    v = getattr(g, attr)
                    if isinstance(v, list):
                        setattr(g, attr, [find(n) for n in v])
                    else:
                        setattr(g, attr, find(v))
        self.V = [0] * len(self.nl.parent)
        self.V[1] = 1

        driver = {}
        for idx, g in enumerate(self.gates):
            for n in g.out_nets():
                driver[n] = idx

        # Kahn topological sort over combinational dependencies.
        n = len(self.gates)
        succ = [[] for _ in range(n)]
        indeg = [0] * n
        for idx, g in enumerate(self.gates):
            seen = set()
            for net in g.comb_in_nets():
                d = driver.get(net)
                if d is not None and d != idx and d not in seen:
                    seen.add(d)
                    succ[d].append(idx)
                    indeg[idx] += 1
        order = [i for i in range(n) if indeg[i] == 0]
        out = []
        qi = 0
        while qi < len(order):
            i = order[qi]
            qi += 1
            out.append(i)
            for j in succ[i]:
                indeg[j] -= 1
                if indeg[j] == 0:
                    order.append(j)
        if len(out) != n:
            raise HDLError("combinational cycle detected in %s" % self.top.name)
        self.order = [self.gates[i] for i in out]
        self.clocked = [g for g in self.gates if g.clocked]

    # -- simulation --------------------------------------------------------
    def eval(self):
        V = self.V
        V[0] = 0
        V[1] = 1
        for g in self.order:
            g.compute(V)

    def tick(self):
        self.eval()
        for g in self.clocked:
            g.capture(self.V)

    def tock(self):
        for g in self.clocked:
            g.commit()
        self.eval()

    # -- variable access ---------------------------------------------------
    def get_instance(self, name):
        lst = self.instances.get(name)
        if not lst:
            raise KeyError("no part named %s in %s" % (name, self.top.name))
        return lst[0]

    def get_var(self, name, index):
        if index is None and name in self.pin_nets:
            return bits_to_val(self.pin_nets[name], self.V)
        inst = self.get_instance(name)
        return inst.get_state(index if index is not None else 0)

    def set_var(self, name, index, value):
        if index is None and name in self.pin_nets:
            val_to_bits(value, self.pin_nets[name], self.V)
            return
        inst = self.get_instance(name)
        inst.set_state(index if index is not None else 0, value)

    def var_width(self, name, index):
        if index is None and name in self.pin_width:
            return self.pin_width[name]
        return 16


# --------------------------------------------------------------------------
# Hack assembler + CPU emulator (for .asm test scripts)
# --------------------------------------------------------------------------

PREDEFINED = {
    "SP": 0, "LCL": 1, "ARG": 2, "THIS": 3, "THAT": 4,
    "SCREEN": 16384, "KBD": 24576,
}
for _i in range(16):
    PREDEFINED["R%d" % _i] = _i

COMP_CODES = {
    "0": 0b0101010, "1": 0b0111111, "-1": 0b0111010, "D": 0b0001100,
    "A": 0b0110000, "!D": 0b0001101, "!A": 0b0110001, "-D": 0b0001111,
    "-A": 0b0110011, "D+1": 0b0011111, "A+1": 0b0110111, "D-1": 0b0001110,
    "A-1": 0b0110010, "D+A": 0b0000010, "D-A": 0b0010011, "A-D": 0b0000111,
    "D&A": 0b0000000, "D|A": 0b0010101,
}
for _k in list(COMP_CODES):
    if "A" in _k:
        COMP_CODES[_k.replace("A", "M")] = COMP_CODES[_k] | 0b1000000
# common alternative spellings accepted by the official assembler
for _a, _b in (("D+A", "A+D"), ("D&A", "A&D"), ("D|A", "A|D"),
               ("D+M", "M+D"), ("D&M", "M&D"), ("D|M", "M|D")):
    COMP_CODES[_b] = COMP_CODES[_a]

JUMP_CODES = {"": 0, "JGT": 1, "JEQ": 2, "JGE": 3, "JLT": 4, "JNE": 5,
              "JLE": 6, "JMP": 7}


def assemble(path):
    with open(path) as fh:
        raw = fh.read()
    lines = []
    for line in raw.split("\n"):
        line = re.sub(r"//.*", "", line).strip()
        line = line.replace(" ", "").replace("\t", "")
        if line:
            lines.append(line)

    symbols = dict(PREDEFINED)
    pc = 0
    body = []
    for line in lines:
        if line.startswith("(") and line.endswith(")"):
            symbols[line[1:-1]] = pc
        else:
            body.append(line)
            pc += 1

    next_var = 16
    code = []
    for line in body:
        if line.startswith("@"):
            sym = line[1:]
            if sym.isdigit():
                val = int(sym)
            else:
                if sym not in symbols:
                    symbols[sym] = next_var
                    next_var += 1
                val = symbols[sym]
            code.append(val & 0x7FFF)
        else:
            jump = ""
            comp = line
            dest = ""
            if ";" in comp:
                comp, jump = comp.split(";", 1)
            if "=" in comp:
                dest, comp = comp.split("=", 1)
            if comp not in COMP_CODES:
                raise ValueError("bad comp %r in %s" % (comp, path))
            if jump not in JUMP_CODES:
                raise ValueError("bad jump %r in %s" % (jump, path))
            d = 0
            if "A" in dest:
                d |= 4
            if "D" in dest:
                d |= 2
            if "M" in dest:
                d |= 1
            code.append(0xE000 | (COMP_CODES[comp] << 6) | (d << 3)
                        | JUMP_CODES[jump])
    return code


def signed16(v):
    v &= 0xFFFF
    return v - 0x10000 if v & 0x8000 else v


class CPUEmulator(object):
    """Behavioural model matching the official CPU emulator's variables."""

    def __init__(self, program):
        self.rom = list(program) + [0] * (32768 - len(program))
        self.ram = [0] * 24577
        self.A = 0
        self.D = 0
        self.PC = 0

    def _comp(self, c):
        a = (c >> 6) & 1
        f = (c >> 0) & 0x3F
        y = self.ram[self.A] if a else self.A
        y &= 0xFFFF
        x = self.D & 0xFFFF
        zx = (f >> 5) & 1
        nx = (f >> 4) & 1
        zy = (f >> 3) & 1
        ny = (f >> 2) & 1
        fn = (f >> 1) & 1
        no = f & 1
        if zx:
            x = 0
        if nx:
            x ^= 0xFFFF
        if zy:
            y = 0
        if ny:
            y ^= 0xFFFF
        out = (x + y) & 0xFFFF if fn else (x & y)
        if no:
            out ^= 0xFFFF
        return out

    def step(self):
        instr = self.rom[self.PC & 0x7FFF]
        if instr & 0x8000 == 0:
            self.A = instr & 0x7FFF
            self.PC = (self.PC + 1) & 0x7FFF
            return
        out = self._comp((instr >> 6) & 0x7F)
        d = (instr >> 3) & 7
        j = instr & 7
        sv = signed16(out)
        jump = ((j & 1 and sv > 0) or (j & 2 and sv == 0) or (j & 4 and sv < 0))
        if d & 1:
            addr = self.A & 0x7FFF
            if addr < len(self.ram):
                self.ram[addr] = out
        if d & 2:
            self.D = out
        if d & 4:
            self.A = out & 0xFFFF
        self.PC = (self.A & 0x7FFF) if jump else ((self.PC + 1) & 0x7FFF)

    def get_var(self, name, index):
        if name in ("RAM", "Memory"):
            return self.ram[index]
        if name == "ROM":
            return self.rom[index]
        if name in ("A", "ARegister"):
            return self.A
        if name in ("D", "DRegister"):
            return self.D
        if name == "PC":
            return self.PC
        raise KeyError(name)

    def set_var(self, name, index, value):
        if name in ("RAM", "Memory"):
            self.ram[index] = value & 0xFFFF
        elif name in ("A", "ARegister"):
            self.A = value & 0xFFFF
        elif name in ("D", "DRegister"):
            self.D = value & 0xFFFF
        elif name == "PC":
            self.PC = value & 0x7FFF
        else:
            raise KeyError(name)

    def var_width(self, name, index):
        return 16


# --------------------------------------------------------------------------
# .tst script parsing / execution
# --------------------------------------------------------------------------

TOKEN_RE = re.compile(r'"[^"]*"|[,;{}]|[^\s,;{}]+')


def tokenize(text):
    return TOKEN_RE.findall(strip_comments(text))


class Fmt(object):
    __slots__ = ("name", "index", "code", "left", "width", "right", "label")

    def __init__(self, spec):
        m = re.match(r"^([A-Za-z_][A-Za-z0-9_]*)(?:\[(\d*)\])?"
                     r"%([BDXS])(\d+)\.(\d+)\.(\d+)$", spec)
        if not m:
            raise ValueError("bad output spec %r" % spec)
        self.name = m.group(1)
        if m.group(2) is None:
            self.index = None
            self.label = self.name
        elif m.group(2) == "":
            self.index = -1  # "[]" -> whole chip value
            self.label = self.name + "[]"
        else:
            self.index = int(m.group(2))
            self.label = "%s[%d]" % (self.name, self.index)
        self.code = m.group(3)
        self.left = int(m.group(4))
        self.width = int(m.group(5))
        self.right = int(m.group(6))

    def total(self):
        return self.left + self.width + self.right

    def header(self):
        t = self.total()
        lab = self.label[:t]
        pad = t - len(lab)
        return " " * (pad // 2) + lab + " " * (pad - pad // 2)

    def render(self, value):
        if self.code == "S":
            s = str(value)[:self.width]
            s = s + " " * (self.width - len(s))
        elif self.code == "B":
            v = int(value) & ((1 << self.width) - 1) if self.width < 64 else int(value)
            s = format(v, "0%db" % self.width)
            s = s[-self.width:]
        elif self.code == "X":
            v = int(value) & 0xFFFF
            s = format(v, "0%dX" % self.width)[-self.width:]
        else:
            s = str(signed16(int(value)))
            s = s.rjust(self.width)[-self.width:] if len(s) > self.width \
                else s.rjust(self.width)
        return " " * self.left + s + " " * self.right


def parse_value(tok):
    tok = tok.strip()
    if tok.startswith("%B") or tok.startswith("%b"):
        return int(tok[2:], 2)
    if tok.startswith("%X") or tok.startswith("%x"):
        return int(tok[2:], 16)
    if tok.startswith("%D") or tok.startswith("%d"):
        return int(tok[2:]) & 0xFFFF
    return int(tok) & 0xFFFF


VAR_RE = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)(?:\[(\d*)\])?$")


def parse_var(tok):
    m = VAR_RE.match(tok)
    if not m:
        raise ValueError("bad variable %r" % tok)
    if m.group(2) is None:
        return m.group(1), None
    if m.group(2) == "":
        return m.group(1), -1
    return m.group(1), int(m.group(2))


class ScriptRunner(object):
    def __init__(self, tst_path, natives=DEFAULT_NATIVES, search_paths=None,
                 max_steps=None, verbose=False):
        self.dir = os.path.dirname(os.path.abspath(tst_path))
        self.path = tst_path
        self.natives = natives
        self.search_paths = search_paths or []
        self.sim = None
        self.kind = None
        self.out_lines = []
        self.out_file = None
        self.cmp_file = None
        self.fmts = []
        self.ticks = 0
        self.phase = 0  # 0 = after tock, 1 = after tick
        self.echo = ""
        self.max_steps = max_steps
        self.verbose = verbose

    # -- variable plumbing -------------------------------------------------
    def _get(self, name, index):
        if name == "time":
            return "%d%s" % (self.ticks, "+" if self.phase else "")
        idx = None if index is None else (None if index == -1 else index)
        return self.sim.get_var(name, idx)

    def _set(self, name, index, value):
        idx = None if index is None else (None if index == -1 else index)
        self.sim.set_var(name, idx, value)

    # -- execution ---------------------------------------------------------
    def run(self):
        with open(self.path) as fh:
            toks = tokenize(fh.read())
        stmts = self._parse_block(toks, 0, len(toks))
        self._exec(stmts)
        return self._finish()

    def _parse_block(self, toks, i, end):
        stmts = []
        cur = []
        while i < end:
            t = toks[i]
            if t == "{":
                depth = 1
                j = i + 1
                while j < end and depth:
                    if toks[j] == "{":
                        depth += 1
                    elif toks[j] == "}":
                        depth -= 1
                    j += 1
                body = self._parse_block(toks, i + 1, j - 1)
                stmts.append(("block", cur, body))
                cur = []
                i = j
                continue
            if t in (",", ";"):
                if cur:
                    stmts.append(("cmd", cur))
                    cur = []
                i += 1
                continue
            cur.append(t)
            i += 1
        if cur:
            stmts.append(("cmd", cur))
        return stmts

    def _exec(self, stmts):
        for st in stmts:
            if st[0] == "cmd":
                self._command(st[1])
            else:
                head, body = st[1], st[2]
                if head and head[0] == "repeat":
                    n = int(head[1]) if len(head) > 1 else 1
                    if self.max_steps is not None:
                        n = min(n, self.max_steps)
                    for _ in range(n):
                        self._exec(body)
                elif head and head[0] == "while":
                    var, index = parse_var(head[1])
                    op = head[2]
                    val = parse_value(head[3])
                    guard = 0
                    while self._cond(self._get(var, index), op, val):
                        self._exec(body)
                        guard += 1
                        if guard > 100000:
                            raise RuntimeError("while loop did not terminate")
                else:
                    raise ValueError("unknown block head %r" % (head,))

    @staticmethod
    def _cond(a, op, b):
        a = signed16(a)
        b = signed16(b)
        return {"=": a == b, "<>": a != b, "<": a < b, ">": a > b,
                "<=": a <= b, ">=": a >= b}[op]

    def _command(self, toks):
        cmd = toks[0]
        if cmd == "load":
            target = toks[1]
            path = os.path.join(self.dir, target)
            if target.endswith(".hdl"):
                self.kind = "hdl"
                self.sim = Simulator(path, self.search_paths, self.natives)
            elif target.endswith(".asm"):
                self.kind = "cpu"
                self.sim = CPUEmulator(assemble(path))
            elif target.endswith(".hack"):
                self.kind = "cpu"
                self.sim = CPUEmulator(load_hack(path))
            else:
                raise ValueError("cannot load %s" % target)
        elif cmd == "output-file":
            self.out_file = os.path.join(self.dir, toks[1])
        elif cmd == "compare-to":
            self.cmp_file = os.path.join(self.dir, toks[1])
        elif cmd == "output-list":
            self.fmts = [Fmt(t) for t in toks[1:]]
            self.out_lines.append(
                "|" + "|".join(f.header() for f in self.fmts) + "|")
        elif cmd == "set":
            if len(toks) >= 4 and toks[1] == "ROM32K":
                raise ValueError("unexpected set form")
            name, index = parse_var(toks[1])
            self._set(name, index, parse_value(toks[2]))
        elif cmd == "eval":
            if self.kind == "hdl":
                self.sim.eval()
        elif cmd == "output":
            if self.kind == "hdl":
                self.sim.eval()
            self._emit()
        elif cmd == "tick":
            self._tick()
        elif cmd == "tock":
            self._tock()
        elif cmd == "ticktock":
            self._tick()
            self._tock()
        elif cmd == "echo":
            self.echo = toks[1].strip('"')
        elif cmd == "clear-echo":
            self.echo = ""
        elif cmd == "breakpoint":
            pass
        elif cmd == "ROM32K":
            # "ROM32K load Foo.hack"
            if len(toks) >= 3 and toks[1] == "load":
                rom = self.sim.get_instance("ROM32K")
                data = load_hack(os.path.join(self.dir, toks[2]))
                rom.mem = list(data) + [0] * (32768 - len(data))
            else:
                raise ValueError("unsupported ROM32K command %r" % (toks,))
        elif cmd in ("vmstep", "repeat", "while"):
            raise ValueError("unexpected %s outside block" % cmd)
        else:
            raise ValueError("unknown command %r" % (toks,))

    def _tick(self):
        if self.kind == "hdl":
            self.sim.tick()
        self.phase = 1

    def _tock(self):
        if self.kind == "hdl":
            self.sim.tock()
        else:
            self.sim.step()
        self.phase = 0
        self.ticks += 1

    def _emit(self):
        cells = []
        for f in self.fmts:
            cells.append(f.render(self._get(f.name, f.index)))
        self.out_lines.append("|" + "|".join(cells) + "|")

    def _finish(self):
        text = "\n".join(self.out_lines) + "\n"
        if self.out_file:
            with open(self.out_file, "w") as fh:
                fh.write(text)
        if not self.cmp_file or not os.path.exists(self.cmp_file):
            return True, "no comparison file"
        with open(self.cmp_file) as fh:
            expected = fh.read().split("\n")
        actual = text.split("\n")
        while expected and expected[-1] == "":
            expected.pop()
        while actual and actual[-1] == "":
            actual.pop()
        if self.max_steps is not None:
            return True, "partial run (%d lines)" % len(actual)
        n = min(len(expected), len(actual))
        for i in range(n):
            if not cmp_line(expected[i], actual[i]):
                return False, ("line %d\n  expected: %s\n  actual:   %s"
                               % (i + 1, expected[i], actual[i]))
        if len(expected) != len(actual):
            return False, ("line count mismatch: expected %d, got %d"
                           % (len(expected), len(actual)))
        return True, "%d lines match" % len(actual)


def cmp_line(exp, act):
    exp = exp.rstrip()
    act = act.rstrip()
    if len(exp) != len(act):
        return False
    for a, b in zip(exp, act):
        if a != "*" and a != b:
            return False
    return True


def load_hack(path):
    out = []
    with open(path) as fh:
        for line in fh:
            line = line.strip()
            if line:
                out.append(int(line, 2))
    return out


# --------------------------------------------------------------------------


def main(argv):
    import argparse
    ap = argparse.ArgumentParser()
    ap.add_argument("tst", nargs="+")
    ap.add_argument("--natives", default=None,
                    help="comma separated list of chips to treat as built-in")
    ap.add_argument("--search", default="",
                    help="comma separated extra HDL search directories")
    ap.add_argument("--max-steps", type=int, default=None)
    args = ap.parse_args(argv[1:])

    natives = DEFAULT_NATIVES
    if args.natives is not None:
        natives = set(x for x in args.natives.split(",") if x)
    search = [p for p in args.search.split(",") if p]

    failures = 0
    for tst in args.tst:
        try:
            runner = ScriptRunner(tst, natives, search, args.max_steps)
            ok, msg = runner.run()
        except Exception as exc:  # pragma: no cover - diagnostics
            ok, msg = False, "%s: %s" % (type(exc).__name__, exc)
        status = "PASS" if ok else "FAIL"
        if not ok:
            failures += 1
        print("%-4s %s  (%s)" % (status, tst, msg.replace("\n", "\n     ")))
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

