// This file is part of www.nand2tetris.org
// and the book "The Elements of Computing Systems"
// by Nisan and Schocken, MIT Press.
// File name: projects/04/Fill.asm

// Runs an infinite loop that listens to the keyboard input.
// When a key is pressed (any key), the program blackens the screen,
// i.e. writes "black" in every pixel;
// the screen should remain fully black as long as the key is pressed.
// When no key is pressed, the program clears the screen, i.e. writes
// "white" in every pixel;
// the screen should remain fully clear as long as no key is pressed.

(MAIN)
   @KBD
   D=M
   @BLACK
   D;JNE            // if a key is pressed, paint black
   @color
   M=0              // color = 0000000000000000 (white)
   @PAINT
   0;JMP
(BLACK)
   @color
   M=-1             // color = 1111111111111111 (black)
(PAINT)
   @SCREEN
   D=A
   @address
   M=D              // address = SCREEN (first word of the screen map)
   @8192
   D=A
   @n
   M=D              // n = 8192 (number of words in the screen map)
(LOOP)
   @color
   D=M
   @address
   A=M
   M=D              // Screen[address] = color
   @address
   M=M+1            // address = address + 1
   @n
   MD=M-1           // n = n - 1
   @LOOP
   D;JGT            // if n > 0 goto LOOP
   @MAIN
   0;JMP            // re-sample the keyboard and repaint

